output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_canyon",
    "text": "Shopping carts are prohibited in single-file aisles bounded by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalRun": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "shelvesOnBothSides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfCanyon": {
          "and": [
            "singleFileHorizontalRun",
            "shelvesOnBothSides"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfCanyon"
        ]
      }
    }
  },
  {
    "id": "no_enter_customer_only_aisle_with_cart",
    "text": "An agent must not enter a customer-only single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W",
            "MOVE"
          ]
        }
      },
      "events": {
        "enterCustomerOnlyAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "moveAction"
            ]
          },
          "post": "singleFileShelfCanyon"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterCustomerOnlyAisleWithCart"
    }
  },
  {
    "id": "must_park_at_narrow_aisle_apron",
    "text": "On reaching the wide apron before the single-file shelf aisle, an agent with a cart is obliged to park the cart before proceeding.",
    "abstraction": {
      "state_properties": {
        "wideCartApron": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                10
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "atApronWithCart": {
          "and": [
            "wideCartApron",
            "hasCart"
          ]
        }
      },
      "events": {
        "parkCartAtApron": {
          "pre": {
            "and": [
              "wideCartApron",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "atApronWithCart",
      "discharge": "parkCartAtApron"
    }
  },
  {
    "id": "must_retrieve_parked_cart",
    "text": "Whenever an agent parks a cart to enter a narrow aisle, the agent is obliged to retrieve the cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "wideCartApron": {
          "and": [
            "at(6,3)",
            {
              "ge": [
                "freeWidthH",
                10
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "parkCartAtApron": {
          "pre": {
            "and": [
              "wideCartApron",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtApron": {
          "pre": {
            "and": [
              "wideCartApron",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtApron",
      "discharge": "retrieveCartAtApron"
    }
  },
  {
    "id": "cartless_only_inside_customer_aisle",
    "text": "After leaving the cart at the apron, moving without the cart is allowed only into the customer-only aisle, not around the wider cart aisles.",
    "abstraction": {
      "state_properties": {
        "cartApron": "at(6,3)",
        "moveAction": {
          "or": [
            "N",
            "S",
            "E",
            "W",
            "MOVE"
          ]
        },
        "notEnteringNarrowAisle": {
          "not": "N"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartApron",
          {
            "not": "hasCart"
          },
          "moveAction",
          "notEnteringNarrowAisle"
        ]
      }
    }
  },
  {
    "id": "no_cartless_service_at_cart_accessible_shelves",
    "text": "Shelf interactions without a cart are prohibited at cart-accessible shelf faces; cartless shelf service is allowed only in the single-file shelf canyon.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartAccessibleShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfCanyon"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "hasCart"
          },
          "cartAccessibleShelfFace"
        ]
      }
    }
  },
  {
    "id": "no_cart_service_inside_single_file_aisle",
    "text": "Items located in the single-file shelf canyon must be handled without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfCanyon"
        ]
      }
    }
  },
  {
    "id": "serve_shelf_from_current_side",
    "text": "If an agent with a cart reaches the upper accessible face of the shelf at the upper aisle, the agent is obliged to serve it from that side rather than going around to the lower face.",
    "abstraction": {
      "state_properties": {
        "upperAccessibleShelfFace": {
          "and": [
            "at(9,4)",
            "shelfS",
            {
              "ge": [
                "freeWidthH",
                10
              ]
            }
          ]
        },
        "upperFaceWithCart": {
          "and": [
            "upperAccessibleShelfFace",
            "hasCart"
          ]
        }
      },
      "events": {
        "serveUpperShelfFace": {
          "pre": {
            "and": [
              "upperAccessibleShelfFace",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "upperFaceWithCart",
      "discharge": "serveUpperShelfFace"
    }
  }
]
